      - name: primary_email
        data_type: VARCHAR
        description: Lexicographically smallest non-NULL email per user; original casing/spaces preserved; empty string if none
      - name: all_emails
        data_type: VARCHAR
        description: Concatenation of all non-NULL emails using ', '; no guaranteed order; duplicates preserved; original casing/spaces preserved; empty string if none
      - name: email_count
